-- ============================================================================
-- 0001 — Esquema base de favorita_stocker en Supabase/Postgres
--
-- Equivalencias con el esquema SQLite v19:
--   box        -> box_type
--   role       -> job_role
--   users      -> profiles (+ auth.users)
--   app_metadata desaparece: la sesión la gestiona Supabase Auth
--
-- Los ids se conservan como bigint para no cambiar los modelos de Dart.
-- Se usa "generated by default as identity" (no "always") para poder
-- importar los ids originales desde SQLite.
-- ============================================================================

create extension if not exists pgcrypto;

-- ---------------------------------------------------------------------------
-- Catálogo
-- ---------------------------------------------------------------------------

create table if not exists public.category (
  id bigint generated by default as identity primary key,
  name text not null unique
);

create table if not exists public.box_type (
  id bigint generated by default as identity primary key,
  type text not null unique,
  units_per_box int not null default 24 check (units_per_box > 0),
  size double precision not null default 1 check (size > 0),
  height double precision not null default 1 check (height > 0),
  width double precision not null default 1 check (width > 0),
  format int not null default 1 check (format > 0),
  trip_capacity int not null default 5 check (trip_capacity > 0),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.product_group (
  id bigint generated by default as identity primary key,
  category_id bigint not null references public.category(id) on delete cascade,
  name text not null,
  image text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (category_id, name)
);

create table if not exists public.subcategory (
  id bigint generated by default as identity primary key,
  group_id bigint not null references public.product_group(id) on delete cascade,
  name text not null,
  unique (group_id, name)
);

create table if not exists public.product (
  id bigint generated by default as identity primary key,
  name text not null,
  box_id bigint not null references public.box_type(id),
  group_id bigint not null references public.product_group(id),
  subcategory_id bigint references public.subcategory(id),
  image text,
  unit_in_stock int not null default 0 check (unit_in_stock >= 0),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz
);

-- ---------------------------------------------------------------------------
-- Consumo
-- ---------------------------------------------------------------------------

create table if not exists public.night (
  id bigint generated by default as identity primary key,
  date date not null unique,
  note text,
  created_at timestamptz not null default now()
);

create table if not exists public.consumption (
  id bigint generated by default as identity primary key,
  night_id bigint not null references public.night(id) on delete cascade,
  product_id bigint not null references public.product(id),
  quantity int not null check (quantity >= 0),
  unique (night_id, product_id)
);

create table if not exists public.special_day (
  date date primary key,
  open boolean not null,
  note text
);

-- ---------------------------------------------------------------------------
-- Turnos y personas
-- ---------------------------------------------------------------------------

create table if not exists public.job_role (
  id bigint generated by default as identity primary key,
  name text not null,
  name_key text not null unique,
  floor text not null default 'planta_baja'
    check (floor in ('planta_baja', 'karaoke', 'terraza')),
  note text not null default '',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.profiles (
  id bigint generated by default as identity primary key,
  auth_id uuid not null unique references auth.users(id) on delete cascade,
  name text not null,
  surname text not null default '',
  email text not null,
  role text not null default 'employee'
    check (role in ('admin', 'employee')),
  job_role_id bigint references public.job_role(id),
  active boolean not null default true,
  opener boolean not null default false,
  working_days text not null default '',
  must_change_password boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- El email se compara sin distinguir mayúsculas.
create unique index if not exists profiles_email_lower_key
  on public.profiles (lower(email));

create table if not exists public.shift (
  id bigint generated by default as identity primary key,
  date date not null,
  user_id bigint not null references public.profiles(id) on delete cascade,
  user_name text not null,
  role_id bigint not null references public.job_role(id),
  role_name text not null,
  floor text not null
    check (floor in ('planta_baja', 'karaoke', 'terraza')),
  start_min int not null check (start_min between 0 and 1439),
  end_min int not null check (end_min between 0 and 1439),
  break_min int not null default 0 check (break_min >= 0),
  status text not null default 'borrador'
    check (status in ('borrador', 'publicado', 'confirmado')),
  note text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (user_id, date)
);

-- ---------------------------------------------------------------------------
-- Índices
-- ---------------------------------------------------------------------------

create index if not exists idx_product_group on public.product(group_id);
create index if not exists idx_product_box on public.product(box_id);
create index if not exists idx_product_subcategory on public.product(subcategory_id);
create index if not exists idx_product_deleted on public.product(deleted_at);
create index if not exists idx_group_category on public.product_group(category_id);
create index if not exists idx_subcategory_group on public.subcategory(group_id);
create index if not exists idx_consumption_product on public.consumption(product_id);
create index if not exists idx_consumption_night on public.consumption(night_id);
create index if not exists idx_shift_date on public.shift(date);
create index if not exists idx_shift_user on public.shift(user_id);
create index if not exists idx_shift_role on public.shift(role_id);

-- ---------------------------------------------------------------------------
-- Vistas de lectura
--
-- Reproducen exactamente las columnas planas que esperan los modelos Dart
-- (Product.fromRow, AppUser.fromRow, etc.). "security_invoker" hace que la
-- RLS de las tablas subyacentes se siga aplicando al consultar la vista.
-- ---------------------------------------------------------------------------

create or replace view public.product_view
with (security_invoker = true) as
select
  p.id,
  p.name,
  p.image,
  p.unit_in_stock,
  p.deleted_at,
  g.image as group_image,
  c.name as category,
  g.name as group_name,
  s.name as subcategory,
  b.type as box_name,
  b.units_per_box,
  b.size,
  b.height,
  b.width,
  b.format,
  b.trip_capacity
from public.product p
join public.product_group g on g.id = p.group_id
join public.category c on c.id = g.category_id
left join public.subcategory s on s.id = p.subcategory_id
join public.box_type b on b.id = p.box_id;

create or replace view public.product_group_view
with (security_invoker = true) as
select g.id, c.name as category, g.name, g.image
from public.product_group g
join public.category c on c.id = g.category_id;

create or replace view public.subcategory_view
with (security_invoker = true) as
select s.id, c.name as category, g.name as grp, s.name
from public.subcategory s
join public.product_group g on g.id = s.group_id
join public.category c on c.id = g.category_id;

create or replace view public.user_view
with (security_invoker = true) as
select
  u.id,
  u.auth_id,
  u.name,
  u.surname,
  u.email,
  u.role,
  (u.active)::int as active,
  (u.opener)::int as opener,
  u.working_days,
  u.must_change_password,
  r.id as role_id,
  r.name as role_name,
  r.floor,
  r.note as role_note
from public.profiles u
left join public.job_role r on r.id = u.job_role_id;

-- ---------------------------------------------------------------------------
-- updated_at automático
-- ---------------------------------------------------------------------------

create or replace function public.touch_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end $$;

do $$
declare
  t text;
begin
  foreach t in array array[
    'box_type', 'product_group', 'product', 'job_role', 'profiles', 'shift'
  ] loop
    execute format(
      'drop trigger if exists trg_%s_touch on public.%I', t, t);
    execute format(
      'create trigger trg_%s_touch before update on public.%I
       for each row execute function public.touch_updated_at()', t, t);
  end loop;
end $$;
